package main
import("bytes";"compress/gzip";"crypto/sha256";"encoding/json";"fmt";"io";"os";"path/filepath";"github.com/minz/minzc/pkg/hir";"github.com/minz/minzc/pkg/pipeline";"reflect")
func must(e error){if e!=nil{panic(e)}}
func read(p string)[]byte{b,e:=os.ReadFile(p);if e==nil{return b};f,e:=os.Open(p+".gz");must(e);defer f.Close();z,e:=gzip.NewReader(f);must(e);defer z.Close();b,e=io.ReadAll(z);must(e);return b}
func main(){root:=os.Args[1];for _,goal:=range []string{"speed","size"}{p:=filepath.Join(root,goal);var selection pipeline.MemoryHostAppendSelection;must(json.Unmarshal(read(filepath.Join(p,"selection.json")),&selection));var profile hir.MemoryHostLoopProfileRun;must(json.Unmarshal(read(filepath.Join(p,"source-profile.json")),&profile));if selection.Schema!="minz.memory-host-append-selection/v1"||selection.Options.Goal!=goal||selection.Options.MaxSites!=1||!reflect.DeepEqual(selection.Profile,&profile)||!reflect.DeepEqual(selection.Association.Profile,&profile)||len(selection.Candidates)!=2{panic("sourceprofile/selection binding")};for j,variant:=range []string{"original","hoisted"}{var saved pipeline.MemoryHostBaselineEvidence;must(json.Unmarshal(read(filepath.Join(p,variant,"factory-baseline.json")),&saved));embedded,e:=json.Marshal(selection.Candidates[j].Evidence);must(e);savedTyped,e:=json.Marshal(saved);must(e);var ev,sv any;must(json.Unmarshal(embedded,&ev));must(json.Unmarshal(savedTyped,&sv));if !reflect.DeepEqual(ev,sv)||selection.Candidates[j].Hoisted!=(j==1){panic("candidate binding")};if j==1{proof:=selection.Candidates[j].PrecompileProof;if proof==nil||proof.Schema!="minz.exact-memory-host-append-hoist-precompile/v1"||proof.Function!="intern_region"||!reflect.DeepEqual(proof.OriginalCompatibility,selection.Candidates[0].Evidence.Compatibility)||!reflect.DeepEqual(proof.ActualCompatibility,selection.Candidates[1].Evidence.Compatibility)||!reflect.DeepEqual(proof.OriginalFunctions,selection.Candidates[0].Evidence.FunctionSites)||!reflect.DeepEqual(proof.ActualFunctions,selection.Candidates[1].Evidence.FunctionSites){panic("precompile typed identities")};found:=false;for _,site:=range profile.Sites.Sites{if site.ID==selection.SiteID{if !reflect.DeepEqual(proof.SourceSite,site){panic("proof source site")};found=true}};if !found{panic("proof site absent")}}}
 a,b:=selection.Candidates[0].Evidence.Target,selection.Candidates[1].Evidence.Target;want:=0;if goal=="speed"&&b.TotalTStates<a.TotalTStates||goal=="size"&&len(b.Binary)<len(a.Binary){want=1};if selection.Selected!=want{panic("winner")};if profile.CompletedCalls!=30||profile.FailedCalls!=0||len(profile.Invocations)!=30{panic("profilecounts")};found:=false;for _,s:=range profile.Sites.Sites{if s.ID==selection.SiteID{if s.Function!="intern_region"||s.HIRPath!="body/s5"{panic("exact append site")};found=true}};if !found{panic("site")};typed,e:=json.Marshal(selection);must(e);profileTyped,e:=json.Marshal(profile);must(e);fmt.Printf("PASS %s sourceprofiletypedSHA%x selectiontypedSHA%x actualwinner%d original%dT/%dB peeled%dT/%dB\n",goal,sha256.Sum256(profileTyped),sha256.Sum256(typed),selection.Selected,a.TotalTStates,len(a.Binary),b.TotalTStates,len(b.Binary));_ = bytes.Equal
}}
